def compute(vars):
    values_thousand = [vars["v1"], vars["v2"], vars["v3"]]
    average_thousand = sum(values_thousand) / len(values_thousand)
    average_millions = average_thousand / 1000
    return {
        "value": average_millions,
        "trace": {
            "values_thousand": values_thousand,
            "average_thousand": average_thousand,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": None
            }
        }
    }
